PutBattleUpdateOnTheAir.body:
TVShow *show;
    u8 name[32];

    sCurTVShowSlot = FindFirstEmptyNormalTVShowSlot(gSaveBlock1Ptr->tvShows);
    if (sCurTVShowSlot != -1)
    {
        TryReplaceOldTVShowOfKind(TVSHOW_BATTLE_UPDATE);
        if (gSpecialVar_Result != TRUE)
        {
