                show->battleUpdate.battleType = 2;
            else if (gBattleTypeFlags & BATTLE_TYPE_DOUBLE)
                show->battleUpdate.battleType = 1;
            else
                show->battleUpdate.battleType = 0;

            show->battleUpdate.move = move;
